using System.Data;using System.Text.Json;using Microsoft.Extensions.Hosting;using Microsoft.Extensions.Logging;
namespace Footing.Framework.Outbox;
public sealed record OutboxMessage(Guid Id,string Type,string Payload,DateTime CreatedAt,DateTime? ProcessedAt=null,int Attempts=0,string? LastError=null);
public interface IOutboxStore{Task SaveAsync(OutboxMessage m,IDbTransaction? tx=null,CancellationToken ct=default);Task<IReadOnlyList<OutboxMessage>> GetUnprocessedAsync(int batch=100,CancellationToken ct=default);Task MarkProcessedAsync(Guid id,CancellationToken ct=default);Task MarkFailedAsync(Guid id,string error,CancellationToken ct=default);}
public static class OutboxExtensions{public static Task SaveEventAsync<T>(this IOutboxStore s,T evt,IDbTransaction? tx=null,CancellationToken ct=default){var p=JsonSerializer.Serialize(evt);var m=new OutboxMessage(Guid.NewGuid(),typeof(T).AssemblyQualifiedName??typeof(T).Name,p,DateTime.UtcNow);return s.SaveAsync(m,tx,ct);}}
public sealed class OutboxProcessor(IOutboxStore store,EventBus.EventBus bus,ILogger<OutboxProcessor>? log=null):BackgroundService{public TimeSpan Interval{get;set;}=TimeSpan.FromSeconds(2);public int BatchSize{get;set;}=100;
protected override async Task ExecuteAsync(CancellationToken ct){log?.LogInformation("OutboxProcessor started");while(!ct.IsCancellationRequested){try{var batch=await store.GetUnprocessedAsync(BatchSize,ct);foreach(var m in batch){ct.ThrowIfCancellationRequested();try{var t=Type.GetType(m.Type);object e=t!=null?JsonSerializer.Deserialize(m.Payload,t)??m.Payload:m.Payload;bus.Publish(e);await store.MarkProcessedAsync(m.Id,ct);}catch(Exception ex){await store.MarkFailedAsync(m.Id,ex.Message,ct);log?.LogError(ex,"Outbox {Id} failed",m.Id);}}}catch(OperationCanceledException){break;}catch(Exception ex){log?.LogError(ex,"poll error");}
try{await Task.Delay(Interval,ct);}catch(OperationCanceledException){break;}}}}
